mapper.select:
select *,pp.P_Name pName,sd.D_Name pCompetentDepartmentName from Qs_Manage_System  qms
left join Pre_Project pp on qms.p_id = pp.P_Id
left join SYS_Department sd on pp.P_Competent_Department = sd.D_Id

    
        and qms.Te_Id = #{params.teId}
    
    
        and qms.p_id = #{params.pId}
    
    
        and pp.p_competent_department = #{params.pCompetentDepartment}
    
    
        
            
                and likePname(#{params.pName},pp.P_Id)=true
            
            
                and pp.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        and pp.P_Code = #{params.pCode}
    
    
        and qms.state = #{params.state}
    
    
        and qms.Create_Uid = #{params.uId}

select P_Id from sys_position
where D_ID = #{dId}
  and P_Remark=#{mark}
